<script setup>
import {onMounted,onUnmounted,ref,computed,nextTick} from 'vue';
import {Download,Trash2,X,Undo2,Redo2,Eraser,Plus,ChevronLeft,ChevronRight,Maximize2,Minus,MousePointer2,ImagePlus,MousePointer} from 'lucide-vue-next';
import {scratchFilename} from './scratchFilename';
import {WIDTH,HEIGHT,recognize,drawStroke,wrapTextLines} from './scratchGeometry';import {makePdf} from './scratchPdf';
const props=defineProps({sessionId:{type:[String,Number],default:'preview'},paperTitle:{type:String,default:''}}),emit=defineEmits(['close']);
const board=ref(null),root=ref(null),tool=ref('pen'),color=ref('#172943'),autoShape=ref(true),minimized=ref(false),expanded=ref(false),exporting=ref(false),message=ref('');
const textDraft=ref(''),textPosition=ref(null),fontSize=ref(28),textInput=ref(null),strokeSize=ref(4);
const palette=['#172943','#d62828','#1f8f4e','#8e44ad'];const laserPoints=ref([]),selectedImage=ref(-1);let imageDrag=null,laserPointer=null;
const fresh=()=>({strokes:[],history:[],future:[]});const pages=ref([fresh()]),index=ref(0),current=computed(()=>pages.value[index.value]);
const key='pyq-scratch-v2-'+props.sessionId;let active=null,drag=null,pointer=null,saveTimer,paintVersion=0;const imageCache=new Map();
const clone=v=>JSON.parse(JSON.stringify(v));
function recordAction(page,action){page.history.push(action);if(page.history.length>40)page.history.shift();page.future=[]}
function recordAppend(page,strokes){recordAction(page,{type:'append',strokes});page.strokes.push(...strokes)}
function recordReplace(page,strokes){recordAction(page,{type:'replace',before:page.strokes.slice(),after:strokes.slice()});page.strokes=strokes.slice()}
function save(){try{const savedPages=pages.value.map(page=>({strokes:page.strokes,history:[],future:[]}));localStorage.setItem(key,JSON.stringify({version:3,pages:savedPages,index:index.value,autoShape:autoShape.value,color:color.value,strokeSize:strokeSize.value}));message.value='Saved on this device.'}catch{message.value='Storage full/unavailable. Export PDF to keep your work.'}}
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(save,300)}
function loadImage(src){if(!imageCache.has(src))imageCache.set(src,new Promise(resolve=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>resolve(null);img.src=src}));return imageCache.get(src)}
async function paint(canvas,strokes){const version=++paintVersion,images=await Promise.all(strokes.map(s=>s.tool==='image'?loadImage(s.src):null));if(version!==paintVersion||canvas!==board.value)return;const ctx=canvas.getContext('2d');if(!ctx)return;ctx.fillStyle='#fff';ctx.fillRect(0,0,WIDTH,HEIGHT);for(let i=0;i<strokes.length;i++){const s=strokes[i];if(s.tool==='image'){const img=images[i];if(img)ctx.drawImage(img,s.x,s.y,s.w,s.h);if(selectedImage.value>=0&&current.value.strokes[selectedImage.value]===s){ctx.save();ctx.strokeStyle='#2563eb';ctx.lineWidth=3;ctx.setLineDash([8,5]);ctx.strokeRect(s.x,s.y,s.w,s.h);ctx.setLineDash([]);ctx.fillStyle='#2563eb';ctx.fillRect(s.x+s.w-10,s.y+s.h-10,20,20);ctx.restore()}}else drawStroke(ctx,s)}if(laserPoints.value.length>1){ctx.save();ctx.strokeStyle='#ff2020';ctx.lineWidth=2.5;ctx.lineJoin='round';ctx.lineCap='round';ctx.shadowColor='#ff2020';ctx.shadowBlur=4;ctx.beginPath();laserPoints.value.forEach((pt,i)=>i?ctx.lineTo(pt.x,pt.y):ctx.moveTo(pt.x,pt.y));ctx.stroke();const tip=laserPoints.value.at(-1);ctx.fillStyle='#ff2020';ctx.beginPath();ctx.arc(tip.x,tip.y,3.5,0,Math.PI*2);ctx.fill();ctx.restore()}else if(laserPoints.value.length===1){ctx.save();ctx.fillStyle='#ff2020';ctx.shadowColor='#ff2020';ctx.shadowBlur=4;ctx.beginPath();ctx.arc(laserPoints.value[0].x,laserPoints.value[0].y,3.5,0,Math.PI*2);ctx.fill();ctx.restore()}}
function render(){if(board.value)paint(board.value,[...current.value.strokes,...(active?[active]:[])])}
function coords(e){const r=board.value.getBoundingClientRect();return {x:Math.max(0,Math.min(WIDTH,(e.clientX-r.left)*WIDTH/r.width)),y:Math.max(0,Math.min(HEIGHT,(e.clientY-r.top)*HEIGHT/r.height))}}
function beginText(position={x:30,y:30}){addText();tool.value='text';textPosition.value=position;message.value='Type directly on the page. Click elsewhere to finish.';nextTick(()=>textInput.value?.focus())}
function finishTyping(e){if(e.key==='Escape'){e.preventDefault();addText()}else if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();addText()}}
function drawLiveSegment(a,b,s){const ctx=board.value?.getContext('2d');if(!ctx)return;ctx.save();ctx.strokeStyle=s.tool==='eraser'?'#ffffff':s.color;ctx.fillStyle=ctx.strokeStyle;ctx.lineWidth=s.tool==='eraser'?28:s.size||4;ctx.lineJoin='round';ctx.lineCap='round';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.restore()}
function drawLaserSegment(a,b){const ctx=board.value?.getContext('2d');if(!ctx)return;ctx.save();ctx.strokeStyle='#ff2020';ctx.lineWidth=2.5;ctx.lineJoin='round';ctx.lineCap='round';ctx.shadowColor='#ff2020';ctx.shadowBlur=4;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.restore()}
function down(e){if(tool.value==='laser'){if(e.pointerType==='mouse'&&e.button!==0)return;laserPointer=e.pointerId;laserPoints.value=[coords(e)];try{board.value.setPointerCapture(e.pointerId)}catch{}render();e.preventDefault();return}if(tool.value==='select'&&!exporting.value){const p=coords(e),items=current.value.strokes;let hit=-1;for(let i=items.length-1;i>=0;i--){const s=items[i];if(s.tool==='image'&&p.x>=s.x&&p.x<=s.x+s.w&&p.y>=s.y&&p.y<=s.y+s.h){hit=i;break}}selectedImage.value=hit;if(hit>=0){const im=items[hit],resize=p.x>=im.x+im.w-24&&p.y>=im.y+im.h-24;imageDrag={idx:hit,resize,ox:p.x,oy:p.y,original:{...im},before:clone(items)};try{board.value.setPointerCapture(e.pointerId)}catch{}}render();e.preventDefault();return}if(tool.value==='text'&&!exporting.value){beginText(coords(e));e.preventDefault();return}if(active||exporting.value||(e.pointerType==='mouse'&&e.button!==0))return;pointer=e.pointerId;active={tool:tool.value,color:color.value,size:strokeSize.value,points:[coords(e)]};try{board.value.setPointerCapture?.(pointer)}catch{}const ctx=board.value.getContext('2d');if(ctx)drawStroke(ctx,active);e.preventDefault()}
function move(e){if(laserPointer!==null&&e.pointerId===laserPointer){if(e.pointerType==='mouse'&&e.buttons===0){up(e);return}let samples=[];try{samples=Array.from(e.getCoalescedEvents?.()||[])}catch{}if(!samples.length)samples=[e];for(const sample of samples){const p=coords(sample),last=laserPoints.value.at(-1);if(!last||Math.hypot(p.x-last.x,p.y-last.y)>.8){laserPoints.value.push(p);if(last)drawLaserSegment(last,p)}}e.preventDefault();return}if(imageDrag&&tool.value==='select'){const p=coords(e),im=current.value.strokes[imageDrag.idx],dx=p.x-imageDrag.ox,dy=p.y-imageDrag.oy;if(imageDrag.resize){im.w=Math.max(60,imageDrag.original.w+dx);im.h=Math.max(60,imageDrag.original.h+dy)}else{im.x=Math.max(0,Math.min(WIDTH-im.w,imageDrag.original.x+dx));im.y=Math.max(0,Math.min(HEIGHT-im.h,imageDrag.original.y+dy))}render();e.preventDefault();return}if(!active||e.pointerId!==pointer)return;let samples=[];try{samples=Array.from(e.getCoalescedEvents?.()||[])}catch{}if(!samples.length)samples=[e];for(const sample of samples){const p=coords(sample),last=active.points.at(-1);if(Math.hypot(p.x-last.x,p.y-last.y)>.8)active.points.push(p)}render();e.preventDefault()}
function up(e){if(laserPointer!==null&&(!e||e.pointerId===laserPointer)){laserPointer=null;laserPoints.value=[];render();return}if(imageDrag){recordAction(current.value,{type:'replace',before:imageDrag.before,after:clone(current.value.strokes)});imageDrag=null;scheduleSave();render();return}if(!active||e&&e.pointerId!==pointer)return;if(e&&Number.isFinite(e.clientX)&&Number.isFinite(e.clientY)){const p=coords(e),last=active.points.at(-1);if(Number.isFinite(p.x)&&Number.isFinite(p.y)&&Math.hypot(p.x-last.x,p.y-last.y)>.8){active.points.push(p);drawLiveSegment(last,p,active)}}const s=active;active=null;pointer=null;let finalStroke=s;
 // Shape detection is useful for short deliberate shapes, but expensive on very long freehand strokes.
 if(autoShape.value&&s.tool==='pen'&&s.points.length<=2000){const shape=recognize(s.points);if(shape){finalStroke={...s,shape};message.value='Shape recognized.'}}
 recordAppend(current.value,[finalStroke]);render();scheduleSave()}
function cancel(e){if(e.pointerId===laserPointer){up(e);return}if(e.pointerId!==pointer)return;up(e)}
function lostCapture(e){if(e&&e.buttons>0)return;up(e)}
function addImageFile(file){if(!file||!file.type.startsWith('image/')||exporting.value)return;const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const scale=Math.min(1,(WIDTH-80)/img.width,(HEIGHT-80)/img.height),w=Math.max(60,img.width*scale),h=Math.max(60,img.height*scale);const imageStroke={tool:'image',src:String(reader.result),x:40,y:40,w,h};recordAppend(current.value,[imageStroke]);selectedImage.value=current.value.strokes.length-1;tool.value='select';render();scheduleSave();message.value='Screenshot added. Use Select to move or resize it; switch to Pen to write over it.'};img.src=String(reader.result)};reader.readAsDataURL(file)}
function pasteImage(e){if(exporting.value)return;const item=Array.from(e.clipboardData?.items||[]).find(it=>it.type.startsWith('image/'));if(!item)return;const file=item.getAsFile();if(!file)return;e.preventDefault();addImageFile(file)}
function dropImage(e){const file=Array.from(e.dataTransfer?.files||[]).find(f=>f.type.startsWith('image/'));if(!file)return;e.preventDefault();addImageFile(file)}
function deleteSelectedImage(){if(selectedImage.value<0)return;const before=clone(current.value.strokes),after=current.value.strokes.filter((_,i)=>i!==selectedImage.value);recordReplace(current.value,after);selectedImage.value=-1;render();scheduleSave()}
function undo(){if(active||!current.value.history.length)return;const action=current.value.history.pop();if(Array.isArray(action)){current.value.future.push(current.value.strokes.slice());current.value.strokes=action}else if(action.type==='append'){current.value.strokes.splice(Math.max(0,current.value.strokes.length-action.strokes.length),action.strokes.length);current.value.future.push(action)}else if(action.type==='replace'){current.value.strokes=action.before.slice();current.value.future.push(action)}render();scheduleSave()}
function redo(){if(active||!current.value.future.length)return;const action=current.value.future.pop();if(Array.isArray(action)){current.value.history.push(current.value.strokes.slice());current.value.strokes=action}else if(action.type==='append'){current.value.strokes.push(...action.strokes);current.value.history.push(action)}else if(action.type==='replace'){current.value.strokes=action.after.slice();current.value.history.push(action)}render();scheduleSave()}
function addText(){if(!textPosition.value)return;if(!textDraft.value.trim()){textPosition.value=null;textDraft.value='';return}
 const start=index.value,ctx=document.createElement('canvas').getContext('2d'),size=Math.max(12,Math.min(72,Number(fontSize.value)||28)),lineHeight=size*1.25;
 if(!ctx){message.value='Text could not be added. Please try again.';return}
 const startX=Math.max(10,Math.min(WIDTH-50,Number(textPosition.value.x)||30)),startY=Math.max(10,Math.min(HEIGHT-lineHeight-10,Number(textPosition.value.y)||30));
 const lines=wrapTextLines(ctx,textDraft.value,Math.max(40,WIDTH-startX-28),size);
 const firstCapacity=Math.max(1,Math.floor((HEIGHT-startY-10)/lineHeight)),nextCapacity=Math.max(1,Math.floor((HEIGHT-40)/lineHeight));
 const chunks=[];chunks.push(lines.slice(0,firstCapacity));for(let i=firstCapacity;i<lines.length;i+=nextCapacity)chunks.push(lines.slice(i,i+nextCapacity));
 while(pages.value.length<start+chunks.length)pages.value.push(fresh());
 chunks.forEach((chunk,i)=>{const page=pages.value[start+i];recordAppend(page,[{tool:'text',color:color.value,text:chunk.join('\n'),fontSize:size,x:i===0?startX:30,y:i===0?startY:30}])});
 textDraft.value='';textPosition.value=null;render();scheduleSave();if(chunks.length>1)message.value='Long text continued across '+chunks.length+' pages.'}
async function select(n){addText();if(active||exporting.value)return;index.value=n;await nextTick();render();scheduleSave()}
async function addPage(){if(active||exporting.value)return;pages.value.push(fresh());await select(pages.value.length-1)}
function clearPage(){if(active||!confirm('Clear this page? Other pages stay safe. You can Undo.'))return;textPosition.value=null;textDraft.value='';recordReplace(current.value,[]);render();scheduleSave()}
async function deletePage(){if(active||!confirm('Delete this page? Other pages stay safe.'))return;textPosition.value=null;textDraft.value='';pages.value.splice(index.value,1);if(!pages.value.length)pages.value.push(fresh());await select(Math.min(index.value,pages.value.length-1))}
async function paintForExport(canvas,strokes){const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,WIDTH,HEIGHT);for(const stroke of strokes){if(stroke.tool==='image'){const img=new Image();img.src=stroke.src;try{await img.decode()}catch{}if(img.complete&&img.naturalWidth)ctx.drawImage(img,stroke.x,stroke.y,stroke.w,stroke.h)}else drawStroke(ctx,stroke)}}
async function exportPdf(){if(exporting.value||active)return;addText();exporting.value=true;message.value='Preparing PDF…';try{
 const images=[];for(const page of pages.value){const canvas=document.createElement('canvas');canvas.width=WIDTH;canvas.height=HEIGHT;await paintForExport(canvas,page.strokes);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.95));if(!blob)throw Error('Canvas export unavailable');images.push(new Uint8Array(await blob.arrayBuffer()))}
 const url=URL.createObjectURL(makePdf(images)),a=document.createElement('a');a.href=url;a.download=scratchFilename(props.paperTitle);a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message.value='PDF exported. Your pages remain on the board.';
 }catch(e){message.value='Export failed: '+e.message}finally{exporting.value=false}}
function dragStart(e){if(expanded.value||e.target.closest('button'))return;const r=root.value.getBoundingClientRect();drag={dx:e.clientX-r.left,dy:e.clientY-r.top};window.addEventListener('pointermove',dragMove);window.addEventListener('pointerup',dragEnd,{once:true})}
function dragMove(e){if(!drag)return;root.value.style.left=Math.max(0,Math.min(window.innerWidth-root.value.offsetWidth,e.clientX-drag.dx))+'px';root.value.style.top=Math.max(0,Math.min(window.innerHeight-40,e.clientY-drag.dy))+'px'}
function dragEnd(){drag=null;window.removeEventListener('pointermove',dragMove)}
async function resizeMode(){expanded.value=!expanded.value;minimized.value=false;await nextTick();render()}
async function minimize(){minimized.value=!minimized.value;await nextTick();render()}
function keyboard(e){e.stopPropagation();if(e.target.closest('input,textarea,select'))return;if(e.ctrlKey||e.metaKey){if(e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}else if(e.key.toLowerCase()==='y'){e.preventDefault();redo()}}}
function close(){addText();up();save();emit('close')}
onMounted(()=>{try{const d=JSON.parse(localStorage.getItem(key)||sessionStorage.getItem(key));if((d?.version===2||d?.version===3)&&Array.isArray(d.pages)&&d.pages.length&&d.pages.every(p=>Array.isArray(p.strokes)&&Array.isArray(p.history)&&Array.isArray(p.future))){pages.value=d.pages;index.value=Math.min(Math.max(0,d.index||0),d.pages.length-1);autoShape.value=!!d.autoShape;if(palette.includes(d.color))color.value=d.color;if([2,3,4,6,8,12].includes(Number(d.strokeSize)))strokeSize.value=Number(d.strokeSize);message.value='Saved board restored.'}}catch{message.value='Saved scratch data could not be restored.'}render();root.value.focus()});
onUnmounted(()=>{clearTimeout(saveTimer);dragEnd();window.removeEventListener('pointerup',dragEnd);save()});
</script>
<template><section ref="root" class="floating-tool scratch-tool scratch-notebook" :class="{expanded,minimized}" role="dialog" aria-label="Scratch board" tabindex="-1" @keydown="keyboard" @paste="pasteImage">
<header class="floating-tool-header" @pointerdown="dragStart"><strong>Scratch board</strong><span>Drag · resize · draw</span><div class="floating-tool-actions"><button title="Expand / restore" @click="resizeMode"><Maximize2 :size="16"/></button><button title="Minimize / restore" @click="minimize"><Minus :size="16"/></button><button title="Close" @click="close"><X :size="17"/></button></div></header>
<template v-if="!minimized"><div class="scratch-toolbar"><button :class="{active:tool==='select'}" @click="tool='select'"><MousePointer2 :size="15"/>Select</button><button :class="{active:tool==='pen'}" @click="tool='pen'">Pen</button><button :class="{active:tool==='laser'}" @click="tool='laser'"><MousePointer :size="15"/>Laser</button><button v-if="selectedImage>=0" @click="deleteSelectedImage"><Trash2 :size="15"/>Delete image</button><button v-for="c in palette" :key="c" class="scratch-color" :class="{active:tool==='pen'&&color===c}" :style="{background:c}" :aria-label="'Pen '+c" @click="if(tool!=='text')tool='pen';color=c;scheduleSave()"></button><label v-if="tool==='pen'" class="scratch-size">Stroke <select v-model.number="strokeSize" aria-label="Stroke size" @change="scheduleSave"><option v-for="s in [2,3,4,6,8,12]" :value="s">{{s}} px</option></select></label><button :class="{active:tool==='eraser'}" @click="tool='eraser'"><Eraser :size="15"/>Eraser</button><button :class="{active:tool==='text'}" @click="beginText()">Type</button><label v-if="tool==='text'">Size<select v-model.number="fontSize" aria-label="Text size"><option v-for="s in [20,28,36,48]" :value="s">{{s}}</option></select></label><label class="shape-toggle"><input type="checkbox" v-model="autoShape" @change="scheduleSave">Auto shape</label></div>
<div class="scratch-pagebar"><button title="Previous page" :disabled="index===0||exporting" @click="select(index-1)"><ChevronLeft :size="16"/></button><span>Page {{index+1}} / {{pages.length}}</span><button title="Next page" :disabled="index===pages.length-1||exporting" @click="select(index+1)"><ChevronRight :size="16"/></button><button :disabled="exporting" @click="addPage"><Plus :size="15"/>Page</button><button title="Undo (Ctrl+Z)" :disabled="!current.history.length" @click="undo"><Undo2 :size="16"/></button><button title="Redo (Ctrl+Y)" :disabled="!current.future.length" @click="redo"><Redo2 :size="16"/></button><button title="Clear current page" @click="clearPage"><Trash2 :size="15"/>Clear</button><button title="Delete current page" @click="deletePage">Delete page</button><button :disabled="exporting" @click="exportPdf"><Download :size="15"/>{{exporting?'Exporting…':'PDF'}}</button></div>
<div class="scratch-canvas-wrap"><div class="scratch-page-surface"><canvas ref="board" :width="WIDTH" :height="HEIGHT" aria-label="Drawing page" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="cancel" @lostpointercapture="lostCapture" @dragover.prevent @drop="dropImage"></canvas><textarea v-if="textPosition" ref="textInput" v-model="textDraft" class="scratch-inline-text" :style="{left:(textPosition.x/WIDTH*100)+'%',top:(textPosition.y/HEIGHT*100)+'%',width:((WIDTH-textPosition.x)/WIDTH*100)+'%',color,fontSize:(fontSize/WIDTH*100)+'cqw'}" rows="6" aria-label="Scratch text" placeholder="Type here…" @blur="addText" @keydown="finishTyping" @pointerdown.stop></textarea></div></div><p class="scratch-message" role="status">{{message||'Paste or drag a screenshot here. Select to move/resize; Pen to annotate; laser stays visible while the pen is down. Canvas scrolls both ways and saves on this device.'}}</p></template></section></template>
